INSERT INTO routes (id, kind, name, region, status, difficulty, distance_km, gain_m, loss_m, date_start, date_end, from_point, to_point, season, forecast_link, bus_link, bdz_link, avtogari_link, route_line, verification_level, transport, huts, risk, days, accommodation, taxis, windy_embed, notes_default) VALUES
('belmeken', 'detailed', 'Белмекен – Юндола – Велинград', 'Рила (юг) / граница с Родопите', 'Идея', 'Среден', 30, 1250, 950, '2026-08-08', '2026-08-09', 'Костенец', 'Велинград', 'Юни – Октомври', 'https://www.google.com/search?q=windy+prognoza+velingrad', 'https://www.busexpress.bg/en/destination/kostenets/velingrad', 'https://razpisanie.bdz.bg/bg/kostenets/velingrad', 'https://avtogari.info/search.php?start=Костенец&end=Велинград', 'Костенец (влак) → х. Белмекен, яз. Белмекен → х. Христо Смирненски → Юндола', 'ДОБРО — потвърден в туристически форум (bulgarian-mountains.com) с точно тази последователност от хижи.', '{"summary":"Влак в двата края (София↔Костенец, Юндола-теснолинейка↔Велинград) — най-удобният вариант транспортно. До х. Христо Смирненски се стига и с кола по асфалт.","car":{"available":true,"text":"До х. Христо Смирненски се стига с кола по асфалтиран път — възможно е такси вместо пешеходната част на ден 2, ако искаш да скъсиш времето.","parkingNote":"Паркинг при хижата; провери проходимост на последните км при дъждовно време."},"public":{"steps":[{"from":"София/Пловдив","to":"Костенец","mode":"Влак (главна линия)","time":"чест / ~1-1.5ч","note":"Костенец е на основната жп линия — лесен достъп."},{"from":"Юндола","to":"Велинград","mode":"Теснолинейка Септември–Велинград–Добринище или автобус","time":"по разписание","note":"Провери час в БДЖ преди тръгване."}]}}'::jsonb, '[{"name":"х. Белмекен","elevation":2208,"beds":39,"officialSource":"БТС официално (btsbg.org, одит 09.07.2026)","officialPhone":"0879 461899","altPhone":"0889 798 586","gps":"42.1930, 23.7495","verified":true,"conflict":"⚠️ РАЗЛИЧАВА СЕ — официалният БТС номер (0879 461899) се разминава с форумния (0889 798 586), както и капацитетът/височината (39 vs 65 места). Обади се на двата преди датата."},{"name":"х. Христо Смирненски","elevation":1758,"beds":60,"officialSource":"БТС официално","officialPhone":"0877 33 29 69","email":"smirnenskihut@gmail.com","gps":"42.1066, 23.7935","verified":true,"conflict":null}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Терен: Ден 1 (Костенец→х. Белмекен) е най-рисковата част — документиран случай на изгубване (5ч30мин станали 11ч). Задължително следвай р. Крайна и се обади на хижаря преди тръгване.","Транспорт: Добре — влак в двата края, най-удобният вариант от всички нови маршрути.","Хижи: Телефоните на Белмекен и Христо Смирненски са потвърдени от 2+ независими извора, но с разминаване за Белмекен (виж таблицата с хижи).","Километри/денивелация: Среден риск за ден 1 — цифрите са оценка (13-16 км, 1000-1450 м), не точен GPX трак. Провери в OsmAnd/bgmountains преди датата."],"conclusion":"Най-сигурният транспортно от новите маршрути (влак-влак), но ден 1 изисква внимание към ориентирането и предварителен съвет от хижаря."}'::jsonb, '[{"date":"Съб. 08.08","label":"София → Костенец","type":"Транспорт","distance":"70 км с влак","gain":"–","time":"1-1.5ч","stay":"–","difficulty":"–"},{"date":"Съб. 08.08","label":"Костенец → х. Белмекен","type":"Преход","distance":"13-16 км (оценка)","gain":"1000-1450м (оценка)","time":"5-6ч","stay":"х. Белмекен","difficulty":"Среден"},{"date":"Нед. 09.08","label":"х. Белмекен → яз. Белмекен","type":"Преход (кратък спуск)","distance":"1-2 км","gain":"-15-20 мин слизане","time":"15-20мин","stay":"–","difficulty":"Лесен"},{"date":"Нед. 09.08","label":"Яз. Белмекен → х. Хр. Смирненски → Юндола","type":"Преход","distance":"16 км","gain":"+50м / -900м","time":"4.5ч","stay":"–","difficulty":"Лесен"},{"date":"Нед. 09.08","label":"Юндола → Велинград","type":"Транспорт","distance":"25 км","gain":"–","time":"по разписание (теснолинейка/автобус)","stay":"–","difficulty":"–"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=10&overlay=rain&product=ecmwf&level=surface&lat=42.0500&lon=23.7500', '⚠️ Задължително обади се на хижаря на х. Белмекен преди тръгване и потвърди актуалното състояние на маркировката за ден 1.'),
('rodopi-orfey', 'detailed', 'Родопи: връх Орфей (+ Каньонът на водопадите)', 'Родопи (Смолян)', 'Планиран', 'Лесен', 19.5, 729, 715, '2026-08-01', '2026-08-02', 'София', 'Смолян', 'Юни – Октомври (сняг по билото до май)', 'https://www.google.com/search?q=windy+prognoza+smolyan', 'https://www.busexpress.bg/en/destination/sofia/smolyan', 'https://razpisanie.bdz.bg/bg/sofia/smolyan', 'https://avtogari.info/search.php?start=София&end=Смолян', 'Каньонът на водопадите (кръгов) – Смолян, Връх Орфей (от параклис след х. Перелик, отиване-връщане)', 'Денивелацията е верифицирана от 2 реални измервания (240м и 280м). Пътят до параклиса потвърден проходим с лека кола от 3+ независими извора.', '{"summary":"Лична кола София↔Смолян (~260 км, ~4-4.5ч). Пътят до х. Перелик/параклиса е проходим с ВСЯКАКВА лека кола — 4x4 не е нужен.","car":{"available":true,"text":"Път до параклиса (1.2 км след х. Перелик): проходим с всякакъв тип лека кола, потвърдено от 3 независими извора (bulgarian-mountains.com, TripJournal, IzBulgaria). Алтернативен маршрут: отбивка Превала (по пътя Смолян–Девин) → 5-6 км до хижата, възможно по-къс от варианта през Стойките.","parkingNote":"⚠️ На паркинга при канйона има хора с джипове, които твърдят, че информационният център е далеч (искат 20 лв превоз) — всъщност е ~15 мин пеша, спести парите."},"public":{"steps":[{"from":"София","to":"Смолян/Езерово","mode":"Автобус","time":"~4-4.5ч","note":"С кола таксито става излишно — виж таксиметрова таблица по-долу само ако пътуваш без кола."}]}}'::jsonb, '[{"name":"х. Перелик","elevation":1969,"beds":35,"officialSource":"ПОТВЪРДЕНО от БТС (одит 09.07.2026)","officialPhone":"0988 800 850","contactName":"Илия Чернев (председател ТД „Перелик“ – Широка лъка)","altPhone":"0886 675 111 (Янко Пелтеков, за контакти)","gps":"41.610195, 24.596352","verified":true,"conflict":null,"staleNumbers":"Старите номера (0886 752 111 / 0889 371 409) са устарели — не са в официалния БТС профил."}]'::jsonb, '{"level":"НИСЪК","color":"emerald","points":["Терен: оценен от местни като „най-лекият от всички родопски първенци и най-маркираният“. Нетото покачване параклис→връх е само +188м, реалното кумулативно е по-голямо заради подсичане на Малък Перелик и Шабалиева Каба.","Сезонност: комент от май 2026 — по склоновете на Голям Перелик все още имало сняг (метър преспи на места). Извън планирания период, но провери свежи отзиви близо до датата.","Паркинг измами: на паркинга при канйона има хора с джипове, предлагащи ненужен превоз до информационния център (~15 мин пеша).","Данни за денивелация: верифицирани от 2 реални измервания (240м и 280м), средна стойност 265м."],"conclusion":"Най-лекият и най-сигурен от планираните преходи — основното внимание е към сезонния сняг по билото и паркинг измамите."}'::jsonb, '[{"date":"Съб. 01.08","label":"София → Смолян/Езерово","type":"Транспорт","distance":"260 км с кола","gain":"–","time":"4-4.5ч","stay":"х. Кристал, Езерово","difficulty":"–"},{"date":"Съб. 01.08","label":"Каньонът на водопадите (кръгов)","type":"Преход","distance":"кръгов, 4 етапа","gain":"не е дадено","time":"3ч","stay":"х. Кристал, Езерово","difficulty":"Лесен"},{"date":"Нед. 02.08","label":"Параклис (след х. Перелик) → връх Орфей → обратно","type":"Преход","distance":"~13 км (туристическа оценка)","gain":"265м всяка посока","time":"5ч с почивки","stay":"–","difficulty":"Лесен"},{"date":"Нед. 02.08","label":"Смолян/Езерово → София","type":"Транспорт","distance":"260 км с кола","gain":"–","time":"4-4.5ч","stay":"–","difficulty":"–"}]'::jsonb, '[{"name":"Семеен хотел Кристал","location":"кв. Езерово, на брега на Керянов гьол","rating":"8.4 (Booking)","price":"80 лв двойна стая","note":"Гледка към скала Невястата; за вечеря наблизо — ресторант Рибката."},{"name":"Хотел Кипарис Алфа","location":"центъра на Смолян","rating":"9.1 (Booking)","price":"120 лв двойна със закуска","note":"По-скъп, но топ локация."}]'::jsonb, '[{"name":"Експрес такси","phone":"0301 6147","note":"Обслужва изрично Смолян, с. Стойките, Широка лъка, Чепеларе, Пампорово — най-вероятният кандидат."},{"name":"Хит такси","phone":"0878 166 161 / 0886 668 866","note":"–"},{"name":"Такси 1 Плюс","phone":"0301 6188","note":"–"},{"name":"Радиотакси","phone":"0301 35059","note":"–"},{"name":"Узунов Трансгруп","phone":"0301 82647","note":"–"}]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=10&overlay=rain&product=ecmwf&level=surface&lat=41.6100&lon=24.5960', '💡 Извор на река Арда е ~35 км в обратна посока — не е включен в плана, защото не се съчетава лесно с връх Орфей в един уикенд.'),
('bezbog-popovo-ezero', 'detailed', 'Хижа „Безбог“ – Попово езеро', 'Пирин', 'Идея', 'Лесна', 7.4, 223, 214, '', '', 'Добринище', 'Добринище', 'Юни – Октомври (лифтът работи целогодишно, зимата — само с опит и разрешителни за НП Пирин)', 'https://www.google.com/search?q=windy+prognoza+bezbog', 'https://www.virail.bg/avtobus-dobrinische-bansko', '', 'https://avtogari.info/search.php?start=София&end=Добринище', 'Добринище (лифт) → х. Гоце Делчев → х. Безбог → Безбожко езеро → Попово езеро → обратно', 'СРЕДНО — разстоянието/денивелацията са от еднопосочен туристически справочник (planinka.bg), не от GPX трак. Телефонът на хижата се разминава между източниците (виж huts.conflict).', '{"summary":"Без директен път за кола до самата хижа — задължителен седалков лифт от Добринище до х. Гоце Делчев, оттам пеша до х. Безбог.","car":{"available":false,"text":"Кола стига само до долната лифтова станция в Добринище. Оттам няма алтернатива на лифта или дълъг пешеходен подход.","parkingNote":"Паркинг при долната станция — безплатен, но неохраняван. Форумни отзиви (bulgarian-mountains.com) съобщават, че оставяне на кола за 4-5 дни е било безопасно, но това не е гаранция."},"public":{"steps":[{"from":"Банско","to":"Добринище","mode":"Автобус (Union Ivkoni / Struma 11)","time":"15-20 мин, чести курсове 08:30-19:48ч","note":"Провери актуално разписание преди тръгване."},{"from":"Добринище","to":"х. Гоце Делчев","mode":"Седалков лифт","time":"27 мин, 3245м, работи 08:30-17:00ч (посл. качване 16:45ч)","note":"12 лв еднопосочно / 18 лв двупосочно (цени 2020г. — провери актуални)."},{"from":"х. Гоце Делчев","to":"х. Безбог","mode":"Пеша","time":"~30-40 мин","note":"Кратък и лек преход между двете хижи."}]}}'::jsonb, '[{"name":"х. Безбог","elevation":2240,"beds":null,"officialSource":"explorebg.com","officialPhone":"+359 74 472120","altPhone":"0888 286 102","gps":"41.733889, 23.524167","verified":true,"conflict":"⚠️ Двата телефона идват от различни източници (explorebg.com срещу предишен запис в базата) — обади се на explorebg номера първо и провери и двата преди датата."}]'::jsonb, '{"level":"НИСЪК","color":"emerald","points":["Терен: оценен като 2/6 (лесно) — широка, добре маркирана зелена пътека, с кратки каменисти участъци.","Логистика: единственият достъп е лифтът — провери работното време и последно качване (16:45ч) преди да планираш деня.","Вода: няма чешми по пътеката — носи поне 1.5л на човек.","Данни: разстоянието/денивелацията са от единичен източник (planinka.bg), не от верифициран GPX — третирай ги като добра, но не абсолютна оценка."],"conclusion":"Най-лекият от трите нови маршрута — основното внимание е към часовете на лифта, не към самия терен."}'::jsonb, '[{"date":"Ден 1","label":"Добринище → лифт → х. Гоце Делчев → х. Безбог","type":"Транспорт + кратък преход","distance":"лифт 3.2км + пеша ~1км","gain":"737м (лифт) + малко пеша","time":"27 мин лифт + 30-40 мин пеша","stay":"х. Безбог","difficulty":"Лесен"},{"date":"Ден 2","label":"х. Безбог → Попово езеро → обратно → лифт надолу","type":"Преход","distance":"7.4 км (там и обратно)","gain":"223м / -214м","time":"~2ч40мин ходене + почивки","stay":"–","difficulty":"Лесен"}]'::jsonb, '[{"name":"х. Безбог","location":"на място, 2240м н.в.","rating":null,"price":null,"note":"Основна нощувка на маршрута — резервирай предварително по телефон."}]'::jsonb, '[]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=11&overlay=rain&product=ecmwf&level=surface&lat=41.7339&lon=23.5242', '⚠️ Обади се на хижа Безбог (+359 74 472120) преди тръгване, за да провериш разписанието на лифта и наличността на места.'),
('bezbog-tevno-ezero', 'detailed', 'Хижа „Безбог“ – заслон „Тевно езеро“', 'Пирин', 'Идея', 'Средна', 15.4, 370, 370, '', '', 'Добринище', 'Добринище', 'Юни – Октомври. Зимата — само с опит, лавинен риск при директно изкачване през Кралевдворска порта.', 'https://www.google.com/search?q=windy+prognoza+tevno+ezero', 'https://www.virail.bg/avtobus-dobrinische-bansko', '', 'https://avtogari.info/search.php?start=София&end=Добринище', 'х. Безбог → езеро Безбог → „Душевадката“ → Попово езеро → Кралевдворска порта → заслон Тевно езеро → обратно', 'СРЕДНО — разстояние/време от туристически блог (svetogled.com), не от GPX трак. GPS координати на заслона потвърдени от 2 независими източника (360mag.bg, БТС).', '{"summary":"Същият лифтов достъп както за Попово езеро (Добринище → х. Гоце Делчев → х. Безбог), но с по-дълъг и по-сериозен преход след хижата.","car":{"available":false,"text":"Без директен път — задължителен лифт до х. Гоце Делчев, оттам пеша.","parkingNote":"Виж бележката за паркинг при маршрута до Попово езеро (същата долна станция)."},"public":{"steps":[{"from":"Банско","to":"Добринище","mode":"Автобус","time":"15-20 мин","note":"Провери актуално разписание."},{"from":"Добринище","to":"х. Гоце Делчев","mode":"Седалков лифт","time":"27 мин, посл. качване 16:45ч","note":"~20 лв двупосочно (провери актуална цена)."},{"from":"х. Гоце Делчев","to":"х. Безбог","mode":"Пеша","time":"~30-40 мин","note":"Общ старт с маршрута до Попово езеро."}]}}'::jsonb, '[{"name":"заслон Тевно езеро","elevation":2510,"beds":35,"officialSource":"БТС + 360mag.bg","officialPhone":"+359 886 397268","altPhone":null,"gps":"41.6989, 23.4828","verified":true,"conflict":"БТС и 360mag.bg се съгласуват за телефона — по-надежден от предишния placeholder номер в базата. Капацитетът (30-40 места) е приблизителен от неофициален източник."}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Терен: Кралевдворска порта е последната камениста част преди заслона — изисква внимание, особено при мокро/студено време.","Зимен риск: лавинна опасност при директно изкачване през портата — предпочита се северен ръб през Валявишките езера, но изисква опит и екипировка.","Вода: няма чешми по маршрута — носи поне 1.5л на човек.","Данни: разстояние/време от единичен блог източник, не GPX верифицирано — третирай като добра приблизителна оценка.","Логистика: зависимост от часовете на лифта (посл. качване 16:45ч) — планирай ранен старт, ако искаш връщане същия ден."],"conclusion":"По-сериозен от маршрута до Попово езеро заради Кралевдворска порта, но напълно управляем лятото с добра подготовка. Зиме — само за опитни с лавинна преценка."}'::jsonb, '[{"date":"Ден 1","label":"Добринище → лифт → х. Гоце Делчев → х. Безбог","type":"Транспорт + кратък преход","distance":"лифт 3.2км + пеша ~1км","gain":"737м (лифт)","time":"27 мин лифт + 30-40 мин пеша","stay":"х. Безбог","difficulty":"Лесен"},{"date":"Ден 2","label":"х. Безбог → заслон Тевно езеро → обратно","type":"Преход","distance":"15.4 км (там и обратно)","gain":"370м / -370м","time":"3ч30мин без почивки едната посока (~7ч общо)","stay":"заслон Тевно езеро (или връщане същия ден)","difficulty":"Среден"}]'::jsonb, '[{"name":"х. Безбог","location":"старт на прехода, 2240м н.в.","rating":null,"price":null,"note":"Нощувка преди тръгване към заслона."},{"name":"заслон Тевно езеро","location":"крайна точка, 2510м н.в.","rating":null,"price":null,"note":"Кухня, столова, електричество от собствена ВЕЦ. Обади се предварително за наличност на места."}]'::jsonb, '[]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=11&overlay=rain&product=ecmwf&level=surface&lat=41.6989&lon=23.4828', '⚠️ Зиме: лавинна опасност при директно изкачване през Кралевдворска порта — предпочети северния ръб през Валявишките езера и провери с ПСС преди тръгване.'),
('izvora-gotsev-vrah', 'detailed', 'Хижа „Извора“ – Гоцев връх', 'Осогово и Средна гора', 'Идея', 'Висока', NULL, 1000, 1000, '', '', 'с. Петрово', 'с. Петрово', 'Целогодишно достъпна хижа (отопление, ток), но изкачването към върха най-добре Май-Октомври.', 'https://www.google.com/search?q=windy+prognoza+slavyanka', '', '', 'https://avtogari.info/search.php?start=София&end=Сандански', 'с. Петрово или с. Голешево → х. Извора → синя маркировка → връх Гоцев (2212м) → обратно', '⚠️ ВНИМАНИЕ ЗА РЕГИОН: планина Славянка не е сред петте текущи региона в приложението — временно сложена в „Осогово и Средна гора“ по указание, докато не се добави отделен регион. ГЕОГРАФСКИ Извора/Гоцев връх НЕ Е в Средна гора. Разстоянието до върха не е потвърдено в нито един източник — само денивелацията (900-1100м) е приблизително оценена. Нужна е допълнителна проверка (GPX или обаждане на хижата) преди да разчиташ на тези числа.', '{"summary":"Три възможни подхода към хижата — от Петрово (най-лесен, асфалт), Голешево (асфалт+местна пътека), или Парил (традиционен, но по-лош път). Личен автомобил е практичен вариант за първите два.","car":{"available":true,"text":"От с. Петрово: 6км, почти изцяло асфалт, лесно достъпен с всякаква кола. От с. Голешево: ~8км, асфалт до кръстовище, после локална пътека. От с. Парил: 15-16км по третокласен междуселски път — препоръчва се 4x4 или обществен транспорт до Петрово с продължение пеша.","parkingNote":"Не е потвърдено конкретно място за паркиране при хижата в намерените източници — провери по телефона преди тръгване."},"public":{"steps":[{"from":"София/Сандански","to":"с. Петрово","mode":"Автобус/маршрутка (общ. Сандански)","time":"неуточнено","note":"Провери разписание на местните превозвачи — не е намерено онлайн разписание в изследването."}]}}'::jsonb, '[{"name":"х. Извора","elevation":704,"beds":50,"officialSource":"360mag.bg / izvora.hija.bg","officialPhone":"+359 88 296 6372","altPhone":"+359 89 920 9077","gps":"41.414077, 23.557324","verified":true,"conflict":"Множество телефони се появяват в различни източници (+359 74 322287, +359 89 920 9977) — обади се на основния номер първо и провери актуалността на останалите."}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Терен: 900-1100м денивелация до връх Гоцев (2212м) — сериозно изкачване, но точното разстояние не е потвърдено в нито един източник.","Достъп до хижата: пътят от Парил е в по-лошо състояние, особено след дъжд — предпочитай Петрово или Голешево с лична кола.","Данни: това е напълно нов маршрут за базата — няма верифициран GPX, форумни отзиви за самия преход до върха, или сезонни предупреждения. Трябва допълнително проучване преди да разчиташ изцяло на тези числа.","Регион: временно категоризиран в „Осогово и Средна гора“ — географски принадлежи на Славянка, отделна планина."],"conclusion":"Обещаващ, но най-слабо верифициран от трите маршрута — препоръчва се обаждане на хижата и допълнително търсене на GPX/форумни описания преди да го планираш конкретно."}'::jsonb, '[{"date":"Ден 1","label":"Петрово/Голешево → х. Извора","type":"Транспорт + лек преход","distance":"6-8 км","gain":"~200-250м (оценка)","time":"неуточнено","stay":"х. Извора","difficulty":"Лесен"},{"date":"Ден 2","label":"х. Извора → връх Гоцев → обратно","type":"Преход","distance":"не е потвърдено","gain":"900-1100м (оценка)","time":"неуточнено","stay":"–","difficulty":"Висок"}]'::jsonb, '[{"name":"х. Извора","location":"704м н.в., подножие на Славянка","rating":null,"price":null,"note":"50 места, 10 стаи (8 със собствен санитарен възел), целогодишно отопление."}]'::jsonb, '[]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=11&overlay=rain&product=ecmwf&level=surface&lat=41.4141&lon=23.5573', '⚠️ Този маршрут е новодобавен и слабо верифициран — обади се на хижа Извора (+359 88 296 6372) за потвърждение на разстоянието и състоянието на пътеката преди да го планираш.'),
('S01', 'detailed', 'Понор I', 'Стара планина', 'Идея', 'Средна', 15, 850, 850, '', '', '', '', 'Април – Ноември', 'https://www.google.com/search?q=weather+Lakatnik+Sofiya', 'https://www.busexpress.bg/', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Лакатник → х. Тръстеная → Бов, с възможни варианти през по-високи карстови ръбове и по-ниски горски отсечки при мокро време.', 'СРЕДНО — базовите данни са дадени от теб; без достъп до допълнителна проверка в момента не мога надеждно да потвърдя хижи, телефони и GPS.', '{"summary":"Най-практичен е старт/финиш с влак по Искърското дефиле; с кола логистиката е удобна, но трансферът между началото и края остава най-често нужният проблем.","car":{"available":true,"text":"Достъпът до Лакатник и Бов е по асфалтови пътища; в района има удобни точки за оставяне на кола, но конкретен GPS за паркинг трябва да се верифицира на място или по актуален източник.","parkingNote":"Подходящи са гара Лакатник и централните зони около Бов; при уикенд и празници има риск от заетост."},"public":{"steps":[{"from":"София","to":"Лакатник","mode":"Влак","time":"около 1–1.5 ч","note":"Най-удобен вариант за старт."},{"from":"Бов","to":"София","mode":"Влак","time":"около 1–1.5 ч","note":"Лесно връщане след маршрута."}]}}'::jsonb, '[{"name":"х. Тръстеная","elevation":null,"beds":null,"officialPhone":"0886 407 495","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Имам само дадения от теб телефон; липсва верифициран втори независим източник в момента."}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Теренът вероятно е карстов, с ориентационни трудности при мъгла и мокро време.","Данните за хижата не са напълно верифицирани и трябва да се потвърдят преди тръгване."],"conclusion":"Маршрутът е подходящ за уикенд без кола, но изисква внимание към ориентацията и актуална проверка на хижата."}'::jsonb, '[{"date":"2026-07-16","label":"Лакатник → х. Тръстеная → Бов","type":"Преход","distance":"15 км","gain":"+850 м","time":"5–7 ч","stay":"Бов","difficulty":"Средна"}]'::jsonb, '[{"name":"Къщи за гости в Лакатник","location":"Лакатник","rating":null,"price":null,"note":"Подходящо за ранно тръгване преди прехода."},{"name":"Къщи за гости в Бов","location":"Бов","rating":null,"price":null,"note":"Подходящо за нощувка след прехода."}]'::jsonb, '[{"name":"Локални таксита от Своге / Лакатник","phone":null,"note":"Обичайно се уговарят по телефон в района; без проверка не добавям номер."}]'::jsonb, 'https://embed.windy.com/embed.html', ''),
('S02', 'detailed', 'Понор II', 'Стара планина', 'Идея', 'Средна', 12, 700, 700, '', '', '', '', 'Април – Ноември', 'https://www.google.com/search?q=weather+Bov+Lakatnik', 'https://www.busexpress.bg/', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Бов → заслон Буковец → Лакатник, с алтернативи по по-ниски горски и черни пътища при влошено време.', 'СРЕДНО — базовите данни са дадени от теб; в тази среда не мога да потвърдя контактите и GPS координатите.', '{"summary":"Железопътната връзка по Искърското дефиле е най-удобна; при кола остава удобен трансфер между Бов и Лакатник.","car":{"available":true,"text":"До Бов и Лакатник се стига по асфалт; маршрутът е удобен за комбинация паркиране в единия край и връщане с влак.","parkingNote":"Провери наличието на места около гара Бов и Лакатник, особено в почивни дни."},"public":{"steps":[{"from":"София","to":"Бов","mode":"Влак","time":"около 1–1.5 ч","note":"Удобен старт от северния край."},{"from":"Лакатник","to":"София","mode":"Влак","time":"около 1–1.5 ч","note":"Удобен финал."}]}}'::jsonb, '[{"name":"заслон Буковец","elevation":null,"beds":null,"officialPhone":null,"altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Разполагам само с дадения от теб телефон; не мога да го съпоставя с независим втори източник без допълнително търсене."}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Ориентацията в Понор при мъгла може да е трудна.","Контактите за заслона не са потвърдени с независим източник в момента."],"conclusion":"Кратък и практичен преход за уикенд, особено ако искаш железопътна логистика в двата края."}'::jsonb, '[{"date":"2026-07-16","label":"Бов → заслон Буковец → Лакатник","type":"Преход","distance":"12 км","gain":"+700 м","time":"4–6 ч","stay":"Лакатник","difficulty":"Средна"}]'::jsonb, '[{"name":"Къщи за гости в Бов","location":"Бов","rating":null,"price":null,"note":"Удобно за старт на следващ ден по Искърското дефиле."},{"name":"Къщи за гости в Лакатник","location":"Лакатник","rating":null,"price":null,"note":"Удобно при късно пристигане или за ранно тръгване."}]'::jsonb, '[{"name":"Локални таксита от Своге / Бов / Лакатник","phone":null,"note":"Полезни за кратък трансфер, ако влакът не съвпада."}]'::jsonb, 'https://embed.windy.com/embed.html', ''),
