('R07', 'detailed', 'Панорамен', 'Рила', 'Планиран', 'Висока', 20, 800, 1100, '', '', '', '', 'Юни – Септември', 'https://www.google.com/search?q=windy+prognoza+Zavrachica', '', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Боровец → (Кайзеров път/маркиран седловинен маршрут) → х. Заврачица → вр. Янчов чал → слизане към Якоруда', 'СРЕДНО — х. Заврачица и панорамни описания потвърждават маршрута и приблизителни стойности за км и денивелация.', '{"summary":"Началото е лесно достъпно от Боровец; край Якоруда има автобусни връзки, но чести трансфери са редки — такси/трансфер препоръчителни.","car":{"available":true,"text":"Паркинг в Боровец; до х. Заврачица могат да се подходи пеша от Боровец или с помощта на горски пътища в зависимост от вариантите.","parkingNote":"Проверете проходимост за последните незастроени километри при дъжд."},"public":{"steps":[{"from":"София","to":"Самоков","mode":"Автобус/влак + автобус/такси","time":"~1–2ч","note":"От Самоков до Боровец автобус/такси."},{"from":"Якоруда","to":"София/Благоевград","mode":"Автобус","time":"редки линии","note":"Проверете разписания предварително."}]}}'::jsonb, '[{"name":"хижа Заврачица","elevation":2178,"beds":75,"officialPhone":"0884791609","altPhone":null,"email":null,"gps":"42.168,23.640","verified":true,"conflict":null}]'::jsonb, '{"level":"ВИСОК","color":"rose","points":["Билни и открити участъци с силен вятър и експозиция; продължително излагане може да е опасно при лошо време.","Инциденти: няма ясно документирани сериозни инциденти в публичните блогове, но има репорти за изморяване и навлизане в мъгла (непотвърдено).","Сезонност: извън лятото частично нестабилни условия, сняг до късна пролет."],"conclusion":"Подходящ за опитни преходници, изисква подготовка и проверка на времето."}'::jsonb, '[{"date":null,"label":"Боровец → х. Заврачица → вр. Янчов чал → Якоруда","type":"Преход (ден 1)","distance":"20 км (прибл.)","gain":"+800м","time":"8–10ч","stay":"х. Заврачица или нощувка в Якоруда","difficulty":"Висок"}]'::jsonb, '[{"name":"Хотели/къщи в Якоруда","location":"Якоруда","rating":null,"price":null,"note":"Опции за нощувка след слизане."},{"name":"Хижата Заврачица","location":"м. Заврачица","rating":null,"price":null,"note":"Капацитет и контакти в планинските портали, но е добре да звъннете предварително."}]'::jsonb, '[{"name":"Локални таксита Якоруда/Самоков","phone":null,"note":"Резервация препоръчителна за трансфер от/до крайната точка."}]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=10&overlay=rain&product=ecmwf&level=surface&lat=42.168&lon=23.640', ''),
('R08', 'detailed', 'Картала', 'Рила', 'Планиран', 'Средна', 15, 950, 950, '', '', '', '', 'Април – Октомври', 'https://www.google.com/search?q=windy+prognoza+Hut+Makedoniya', '', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Благоевград → (трансфер/такси/автобус) → х. Македония → през билото/пътеки към Семково или Рилски манастир', 'ДОБРО — х. Македония е добре описана в туристически източници с надморска височина и капацитет.', '{"summary":"Крайни точки (Благоевград, Семково/Рилски манастир) имат автобусни връзки; началният достъп до х. Македония изисква трансфер/пешеходно навлизане по планински пътища.","car":{"available":false,"text":"До самата хижа Македония няма директен асфалтов достъп за лични коли (често се достига пеш/със специални 4x4 при договорен трансфер).","parkingNote":"Паркинг в Благоевград/Семково; уточнете за локални горски пътища."},"public":{"steps":[{"from":"Благоевград","to":"Семково/Рилски манастир","mode":"Автобус/микробус","time":"1–2ч","note":"Проверете редовността на линии към селата/кътовете."},{"from":"Семково","to":"хижа Македония","mode":"такси/трансфер/пеша","time":"перементно","note":"Често използват групови трансфери/таксита."}]}}'::jsonb, '[{"name":"хижа Македония","elevation":2166,"beds":40,"officialPhone":"0898564977","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Статус и височина, както и контакт 089 856 4977, са посочени в туристически публикации и сайт Planinka; липсват допълнителни официални телефонни номера във видимите източници."}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Терен: планински пътеки с изкачвания — не чрез технически участъци, но с дължина и износване; маркировката е смесена.","Инциденти: няма значими документирани сериозни случаи в общодостъпните ресурси.","Сезонност: зимен достъп изисква опит и екипировка."],"conclusion":"Подходящ за повечето добре подготвени туристи; осигурете логистика за трансфер."}'::jsonb, '[{"date":null,"label":"Благоевград → х. Македония"